/// <summary>       
/// Form events for RetailPricingSimulator
/// </summary>
internal final class METRetailPricingSimulator_FormEvents
{

    
}

Method.Source:
    /// <summary>
    /// RetailPricingSimulatorSalesLine_OnInitValue
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [FormDataSourceEventHandler(formDataSourceStr(RetailPricingSimulatorV2, RetailPricingSimulatorSalesLine), FormDataSourceEventType::InitValue)]
    public static void RetailPricingSimulatorSalesLine_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormDataSource                          ds              = sender;
        FormRun                                 fr              = ds.formRun();
        RetailPricingSimulatorSalesLine         simSalesLine    = ds.cursor();
        RetailPricingSimulatorSalesTransaction  simSalesTrans   = fr.dataHelper().FindDataSource(formDataSourceStr(RetailPricingSimulatorV2, RetailPricingSimulatorSalesTransaction)).cursor();
        InventDim                               inventDim       = fr.dataHelper().FindDataSource(formDataSourceStr(RetailPricingSimulatorV2, InventDim)).cursor();

        inventDim.InventSiteId      = CustTable::find(simSalesTrans.CustAccount).InventSiteId;
        simSalesLine.InventDimId    = InventDim::findOrCreate(inventDim).inventDimId;
    }

    /// <summary>
    /// InventSiteId_OnModified
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [FormDataFieldEventHandler(formDataFieldStr(RetailPricingSimulatorV2, InventDim, InventSiteId), FormDataFieldEventType::Modified)]
    public static void InventSiteId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource                  ds              = sender.datasource();
        FormRun                         fr              = ds.formRun();
        Object                          frObj           = fr;
        RetailPricingSimulatorSalesLine simSalesLine    = fr.dataHelper().FindDataSource(formDataSourceStr(RetailPricingSimulatorV2, RetailPricingSimulatorSalesLine)).cursor();
        InventDim                       inventDim       = ds.cursor();

        simSalesLine.metUpdateFromItemSiteSettings(inventDim);        
        frObj.calculatePricesAndDiscounts();            
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(RetailPricingSimulatorV2, RetailPricingSimulatorSalesLine), FormDataSourceEventType::Writing)]
    public static void RetailPricingSimulatorSalesLine_OnWriting(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun                         fr              = sender.formRun();
        Object                          frObj           = fr;                    
        RetailPricingSimulatorSalesLine simSalesLine    = sender.cursor();
        InventDim                       inventDim       = fr.dataHelper().FindDataSource(formDataSourceStr(RetailPricingSimulatorV2, InventDim)).cursor();

        if(frObj.metParmModifyingItemID())
        {
            simSalesLine.metUpdateFromItemSiteSettings(inventDim);
            frObj.metParmModifyingItemID(false);
        }      
    }

/// <summary>
/// MPJ_26540_PriceSimulatorChanges
/// METUnitOfMeasureConversion_OnClicked
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormControlEventHandler(formControlStr(RetailPricingSimulatorV2, METUnitOfMeasureConversion), FormControlEventType::Clicked)]
public static void METUnitOfMeasureConversion_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun fr = sender.formRun();
    RetailPricingSimulatorSalesLine simSalesLine = fr.dataHelper().FindDataSource(formDataSourceStr(RetailPricingSimulatorV2, RetailPricingSimulatorSalesLine)).cursor();
    if(simSalesLine && simSalesLine.Product)
    {
        Args args = new Args();
        args.record(EcoResProduct::find(simSalesLine.Product));
        args.menuItemName(menuItemDisplayStr(METUnitOfMeasureConversionView));
        new MenuFunction(menuItemDisplayStr(METUnitOfMeasureConversionView), MenuItemType::Display).run(args);
    }
}
